import java.util.Scanner

typealias Mat = Array<LongArray>

fun mul(a: Mat, b: Mat, mod: Long): Mat {
    val m = a.size
    val k = a[0].size
    val n = b[0].size
    val c = Array(m) { LongArray(n) }
    for (i in 0 until m) {
        for (k2 in 0 until k) {
            val aik = a[i][k2]
            if (aik == 0L) continue
            for (j in 0 until n) {
                c[i][j] = (c[i][j] + aik * b[k2][j]) % mod
            }
        }
    }
    return c
}

fun qPow(base: Mat, exp: Long, mod: Long): Mat {
    val size = base.size
    var ans = Array(size) { LongArray(size) }
    for (i in 0 until size) ans[i][i] = 1
    var baseCopy = base
    var e = exp
    while (e > 0) {
        if (e and 1L == 1L) {
            ans = mul(ans, baseCopy, mod)
        }
        baseCopy = mul(baseCopy, baseCopy, mod)
        e = e shr 1
    }
    return ans
}

fun main() {
    val scanner = Scanner(System.`in`)
    while (scanner.hasNextLong()) {
        val n = scanner.nextLong()
        val sx = scanner.nextLong()
        val sy = scanner.nextLong()
        val dx = scanner.nextLong()
        val dy = scanner.nextLong()
        val t = scanner.nextLong()

        val sx0 = sx - 1
        val sy0 = sy - 1

        val a = arrayOf(
            longArrayOf(2, 1, 1, 0, 1, 2),
            longArrayOf(1, 2, 0, 1, 1, 2),
            longArrayOf(1, 1, 1, 0, 1, 2),
            longArrayOf(1, 1, 0, 1, 1, 2),
            longArrayOf(0, 0, 0, 0, 1, 1),
            longArrayOf(0, 0, 0, 0, 0, 1)
        )

        val aPow = qPow(a, t, n)

        val b = Array(6) { LongArray(1) }
        b[0][0] = sx0
        b[1][0] = sy0
        b[2][0] = ((dx % n) + n) % n
        b[3][0] = ((dy % n) + n) % n
        b[4][0] = 0
        b[5][0] = 1

        val res = mul(aPow, b, n)
        println("${res[0][0] + 1} ${res[1][0] + 1}")
    }
}

